/**
 * Refresh the German bank code table that fills the BIC and bank name from an
 * IBAN. The source is the Deutsche Bundesbank Bankleitzahlendatei, which is
 * published under <https://www.bundesbank.de/de/aufgaben/unbarer-zahlungsverkehr/serviceangebot/bankleitzahlen/download-bankleitzahlen-602592>.
 *
 * Only active payment-service providers (Merkmal 1, not deleted) with a BIC
 * are kept, one row per Bankleitzahl. The generated file is imported by
 * `src/domain/bank-codes.ts`.
 *
 * Usage:
 *   bun run data:bank-codes
 *   bun run data:bank-codes -- --file /path/to/blz-aktuell-csv-data.csv
 */
import fs from "node:fs/promises";
import path from "node:path";

const DOWNLOAD_PAGE =
  "https://www.bundesbank.de/de/aufgaben/unbarer-zahlungsverkehr/serviceangebot/bankleitzahlen/download-bankleitzahlen-602592";
const OUTPUT = path.join(process.cwd(), "src/domain/bank-codes.data.ts");

type Row = {
  bankCode: string;
  bic: string;
  name: string;
};

function option(args: string[], name: string): string | undefined {
  const index = args.indexOf(name);
  if (index < 0) return undefined;
  const value = args[index + 1];
  if (!value || value.startsWith("--")) throw new Error(`"${name}" needs a value.`);
  return value;
}

/** The Bundesbank publishes the CSV in ISO 8859-15, not UTF-8. */
function decode(bytes: Uint8Array): string {
  return new TextDecoder("iso-8859-15").decode(bytes);
}

async function download(): Promise<Uint8Array> {
  const page = await (await fetch(DOWNLOAD_PAGE)).text();
  const link = page.match(/href="([^"]*blz-aktuell-csv-data\.csv)"/i)?.[1];
  if (!link) throw new Error("The Bundesbank page has no current CSV link.");
  const url = new URL(link, DOWNLOAD_PAGE).toString();
  const response = await fetch(url);
  if (!response.ok) throw new Error(`The bank code file could not be downloaded (${response.status}).`);
  return new Uint8Array(await response.arrayBuffer());
}

function parseLine(line: string): string[] {
  const cells: string[] = [];
  let cell = "";
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (quoted) {
      if (char === '"') {
        if (line[index + 1] === '"') {
          cell += '"';
          index += 1;
        } else {
          quoted = false;
        }
      } else {
        cell += char;
      }
    } else if (char === '"') {
      quoted = true;
    } else if (char === ";") {
      cells.push(cell);
      cell = "";
    } else {
      cell += char;
    }
  }
  cells.push(cell);
  return cells;
}

function rows(csv: string): Row[] {
  const [header, ...lines] = csv.replace(/^\uFEFF/, "").split(/\r?\n/);
  const columns = parseLine(header ?? "");
  const codeIndex = columns.indexOf("Bankleitzahl");
  const kindIndex = columns.indexOf("Merkmal");
  const nameIndex = columns.indexOf("Bezeichnung");
  const bicIndex = columns.indexOf("BIC");
  const changeIndex = columns.indexOf("Änderungskennzeichen");
  if ([codeIndex, kindIndex, nameIndex, bicIndex, changeIndex].some((index) => index < 0)) {
    throw new Error("The bank code file has an unexpected header.");
  }
  const seen = new Set<string>();
  const kept: Row[] = [];
  for (const line of lines) {
    if (!line.trim()) continue;
    const cells = parseLine(line);
    const bankCode = (cells[codeIndex] ?? "").trim();
    const bic = (cells[bicIndex] ?? "").trim().toUpperCase();
    const name = (cells[nameIndex] ?? "").replace(/\s+/g, " ").trim();
    if (!/^\d{8}$/.test(bankCode) || !bic) continue;
    if ((cells[kindIndex] ?? "").trim() !== "1") continue;
    if ((cells[changeIndex] ?? "").trim() === "D") continue;
    if (seen.has(bankCode)) continue;
    seen.add(bankCode);
    kept.push({ bankCode, bic, name });
  }
  return kept.sort((left, right) => left.bankCode.localeCompare(right.bankCode));
}

function templateLiteral(raw: string): string {
  return raw.replaceAll("\\", "\\\\").replaceAll("`", "\\`").replaceAll("${", "\\${");
}

async function main() {
  const file = option(process.argv.slice(2), "--file");
  const bytes = file ? await fs.readFile(file) : await download();
  const kept = rows(decode(bytes));
  const data = kept.map((row) => `${row.bankCode}\t${row.bic}\t${row.name}`).join("\n");
  const stamp = new Date().toISOString().slice(0, 10);
  const source = `/**
 * German Bankleitzahlen with BIC and bank name.
 *
 * Generated by \`scripts/build-bank-codes.ts\` on ${stamp} from the
 * Deutsche Bundesbank Bankleitzahlendatei. Do not edit by hand.
 * Only active payment-service providers (Merkmal 1, not deleted) are kept.
 */
export const BANK_CODES = \`${templateLiteral(data)}\`;
`;
  await fs.writeFile(OUTPUT, source, "utf8");
  console.log(`Wrote ${kept.length} bank codes to ${path.relative(process.cwd(), OUTPUT)}.`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});